using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Por.Core;
class Host:IGameIoHost{
 public Queue<byte> Keys=new Queue<byte>();public List<string> Events;public bool KeyPressed{get{return false;}}public byte ReadKey(){Events.Add("key");return Keys.Count>0?Keys.Dequeue():(byte)13;}public void SoundCommand(ushort c){throw new Exception("unexpected sound");}public void SoundSuspend(){throw new Exception();}public void Interrupt(byte n,Types.TInterruptRegisters r){throw new Exception();}public void Halt(int code){throw new Exception();}public void WriteLine(string s){throw new Exception();}public TextWriter OpenDebugLog(string p){throw new Exception();}
}
class Tests{
 static long checks;static List<string> events=new List<string>();static Host host=new Host{Events=events};static void Yes(bool b,string m){checks++;if(!b)throw new Exception(m);}static string G(int x,int y,int c,int g){return "g:"+x+":"+y+":"+c+":"+g;}static int Glyph(int b){return(b>=97&&b<=122?b-32:b)%64;}
 static void Setup(){GDVars.gameFont=new Types.TFontArr();GDVars.video.DrawGlyph=(x,y,c,g)=>events.Add(G(x,y,c,g));GDVars.video.ClearRect=(l,t,r,b)=>events.Add("c:"+l+":"+t+":"+r+":"+b);GDVars.video.ClearScreen=()=>events.Add("screen");TextRend.DelayMilliseconds=n=>events.Add("d:"+n);GameIo.Host=host;GDVars.stingArg=false;events.Clear();}
 static void Glyphs(){
  for(int ch=0;ch<256;ch++)for(int ascii=0;ascii<2;ascii++)foreach(int count in new[]{0,1,3,255}){
   events.Clear();TextRend.RenderChar(39,24,231,(byte)count,(byte)ch,(byte)ascii);int n=ascii!=0||ch<177?count:0;Yes(events.Count==n,"glyph count");for(int k=0;k<n;k++)Yes(events[k]==G((39+k)&255,24,231,ascii!=0?Glyph(ch):ch),"direct/ASCII glyph and byte column wrap");
  }
  GDVars.gameFont=null;events.Clear();TextRend.RenderChar(0,0,1,4,65,1);Yes(events.Count==0,"unloaded font no-op");GDVars.gameFont=new Types.TFontArr();TextRend.RenderChar(40,0,1,4,65,1);TextRend.RenderChar(0,25,1,4,65,1);Yes(events.Count==0,"offscreen starts no-op");
  string text=new string('a',255);events.Clear();TextRend.DisplayString(10,2,9,text);var want=new List<string>();for(int i=0;i<255;i++){int x=(10+i)&255;if(x<=39)want.Add(G(x,2,9,1));}Yes(events.SequenceEqual(want),"DisplayString independently guards each wrapped char");events.Clear();TextRend.DisplayString(0,30,9,"abc");Yes(events.Count==0,"DisplayString row39 guard then glyph row24 guard");
  for(int l=0;l<40;l++)for(int r=l;r<40;r++){string s="centered title";events.Clear();TextRend.DisplayCentered((byte)l,(byte)r,5,14,s);int len=Math.Min(s.Length,r-l+1),x=l+(r-l+1-len)/2;Yes(events.Count==len,"center truncated length");for(int i=0;i<len;i++)Yes(events[i]==G(x+i,5,14,Glyph(s[i])),"center positions");}
 }
 static void Rects(){var rng=new Random(7021);for(int i=0;i<8000;i++){sbyte l=unchecked((sbyte)rng.Next(256)),t=unchecked((sbyte)rng.Next(256)),r=unchecked((sbyte)rng.Next(256)),b=unchecked((sbyte)rng.Next(256));events.Clear();TextRend.ClearRect(l,t,r,b);bool valid=l>=0&&t>=0&&l<=r&&t<=b&&r<=39&&b<=24;Yes(events.Count==(valid?1:0),"signed rect guard");if(valid)Yes(events[0]=="c:"+l+":"+t+":"+r+":"+b,"rect delegate");}
  events.Clear();TextRend.ClearScreen();Yes(events.SequenceEqual(new[]{"screen"}),"clear driver");TextRend.ClearBottomLine();Yes(events.Count==41,"bottom forty glyphs");
 }
 static void Windows(){using(var doc=JsonDocument.Parse(File.ReadAllText("evidence/three-more-2026-10-21/text-windows.json"))){int n=0;foreach(var c in doc.RootElement.EnumerateArray()){var a=c.GetProperty("args");var e=c.GetProperty("expected");events.Clear();GDVars.curCol=a[7].GetByte();GDVars.curRow=a[8].GetByte();GDVars.msgDelayFlag=(byte)(a[9].GetBoolean()?1:0);GDVars.gameDelay=a[10].GetByte();TextRend.DisplayMessageWindow(a[0].GetByte(),a[1].GetByte(),a[2].GetByte(),a[3].GetByte(),a[4].GetByte(),a[5].GetBoolean(),a[6].GetString());Yes(GDVars.curCol==e[0].GetInt32()&&GDVars.curRow==e[1].GetInt32(),"window cursor case"+n);var want=e[2].EnumerateArray().Select(v=>v.GetString()).ToArray();Yes(events.SequenceEqual(want),"window exact event trace case"+n);n++;}}GDVars.msgDelayFlag=0;
  events.Clear();GDVars.curCol=255;GDVars.curRow=255;TextRend.ShowMessage(7,true,"hi");Yes(events[0]=="c:1:17:38:22"&&GDVars.curCol==3&&GDVars.curRow==17,"ShowMessage fixed bounds");
 }
 static void Timing(){int[] ticks={10,11,12,12};int ix=0;TextRend.ReadBiosTicks=()=>ticks[ix++];Yes(TextRend.TickCount()==12&&ix==4,"read until consecutive stable");for(int t=0;t<=1573040;t+=137){int now=t;TextRend.ReadBiosTicks=()=>now;Yes(TextRend.GetTicks()==(long)now*54925/10000,"centisecond split");}TextRend.ReadBiosTicks=null;bool fail=false;try{TextRend.TickCount();}catch(NotSupportedException){fail=true;}Yes(fail,"tick missing host fails");
  for(int d=0;d<256;d++){events.Clear();GDVars.gameDelay=(byte)d;TextRend.PauseOnly();Yes(events.SequenceEqual(new[]{"d:"+(d*225)}),"pause scale");}TextRend.DelayMilliseconds=null;fail=false;try{TextRend.PauseOnly();}catch(NotSupportedException){fail=true;}Yes(fail,"delay missing host fails");TextRend.DelayMilliseconds=n=>events.Add("d:"+n);
  events.Clear();TextRend.DisplayAndPause(14,"test");Yes(events.Count==45&&events[44]=="key","DisplayAndPause order");events.Clear();GDVars.gameDelay=3;TextRend.PrintAndPause("hi",5);Yes(events.Count==83&&events[42]=="d:675"&&!events.Contains("key"),"PrintAndPause no keywait");
 }
 static void Input(){
  host.Keys=new Queue<byte>(new byte[]{97,98,8,99,27});events.Clear();Yes(TextRend.ReadString("Q",2,9)=="AC","backspace and escape retains reply");Yes(events.Contains(G(2,24,15,1))&&events.Contains(G(3,24,15,2))&&events.Contains(G(3,24,0,32))&&events.Contains(G(3,24,15,3)),"source increment-before-echo columns");
  host.Keys=new Queue<byte>(new byte[]{0,122,123,65,66,13});Yes(TextRend.ReadString("",1,2)=="ZA","printable range and maxLen");host.Keys=new Queue<byte>(Enumerable.Repeat((byte)97,50).Concat(new byte[]{13}));Yes(TextRend.ReadString("",1,50)==new string('A',40),"TStr40 result truncation");
  foreach(string text in new[]{"0","65535","+42","$FF"," 31","$FFFF"}){host.Keys=new Queue<byte>(text.Select(c=>(byte)c).Concat(new byte[]{13}));ushort actual=TextRend.InputUint16("n",7);int want=text.Trim().StartsWith("$")?Convert.ToInt32(text.Trim().Substring(1),16):int.Parse(text);Yes(actual==want,"Val valid "+text);}
  foreach(string text in new[]{"65536","-1","1x","1 ","","999999","$10000"}){host.Keys=new Queue<byte>(text.Select(c=>(byte)c).Concat(new byte[]{13,52,50,13}));Yes(TextRend.InputUint16("n",7)==42&&host.Keys.Count==0,"Val retry invalid "+text);}
 }
 static void Font(){string dir=Path.Combine(Path.GetTempPath(),"por-font-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{GDVars.gameDir=dir+Path.DirectorySeparatorChar;GDVars.dsSuppressingInsertDiskFlag=true;GDVars.virtualDisk=1;DaxIo.ResetArchiveCache();byte[] raw=Enumerable.Range(0,1600).Select(i=>unchecked((byte)(i*17))).ToArray();var packed=new List<byte>();for(int at=0;at<raw.Length;at+=126){int n=Math.Min(126,raw.Length-at);packed.Add((byte)(n-1));packed.AddRange(raw.Skip(at).Take(n));}using(var b=new BinaryWriter(File.Create(Path.Combine(dir,"8x8d1.dax")))){b.Write((ushort)9);b.Write((byte)201);b.Write(0);b.Write((ushort)raw.Length);b.Write((ushort)packed.Count);b.Write(packed.ToArray());}GDVars.gameFont=new Types.TFontArr();var original=GDVars.gameFont;TextRend.LoadGameFont();Yes(Object.ReferenceEquals(original,GDVars.gameFont),"font copied into existing object");for(int i=0;i<1416;i++)Yes(GDVars.gameFont[i/8,i%8]==raw[i],"font exact bounded bytes");File.Delete(Path.Combine(dir,"8x8d1.dax"));DaxIo.ResetArchiveCache();TextRend.LoadGameFont();Yes(GDVars.gameFont[176,7]==raw[1415],"missing font leaves current");}finally{DaxIo.ResetArchiveCache();Directory.Delete(dir,true);}}
 static void Main(){Setup();Glyphs();Rects();Windows();Timing();Input();Font();Console.WriteLine("TextRend source-derived assertions: "+checks);}
}
